mapper.select:
SELECT t.id AS task_id,o.observation_id AS part_id,a.finished_at AS occurred_at FROM ai_task t LEFT JOIN ai_attempt a ON a.owner_id=t.owner_id AND a.task_id=t.id AND a.id=t.current_attempt_id LEFT JOIN JSON_TABLE( CASE WHEN JSON_TYPE(JSON_EXTRACT(t.candidate_json,'$.observations'))='ARRAY' THEN JSON_EXTRACT(t.candidate_json,'$.observations') ELSE JSON_ARRAY() END, '$[*]' COLUMNS(observation_id VARCHAR(16) PATH '$.id' NULL ON EMPTY ERROR ON ERROR) ) AS o ON TRUE WHERE t.owner_id=#{owner} AND t.purpose='ANSWER_EVALUATION' AND t.status='SUCCEEDED' AND (a.finished_at IS NULL OR (a.finished_at>=#{startAt} AND a.finished_at<#{observedUntil}))
AND (a.finished_at IS NULL OR a.finished_at<#{afterAt} OR (a.finished_at=#{afterAt} AND (t.id>#{afterTaskId} OR (t.id=#{afterTaskId} AND CAST(o.observation_id AS BINARY)>CAST(#{afterPartId} AS BINARY)))))
ORDER BY (a.finished_at IS NULL) DESC,a.finished_at DESC,t.id ASC,CAST(o.observation_id AS BINARY) ASC LIMIT #{limit}
